-- Generated by official Supabase CLI3 migration new, 2026-11-14; candidate only.
-- Additive observation/review ledger. No payment, licence, invoice, email or
-- provider mutation. Existing migrations/financial DTOs are intentionally intact.
-- The Edge acceptance flag is OFF until isolated/native/provider acceptance.
create table private.tc_subscription_risk_entries(
 id uuid primary key default gen_random_uuid(),
 case_id uuid not null references private.tc_subscription_risk_entries(id) on delete restrict,
 task_id uuid not null references private.tc_manual_subscription_invoice_tasks(id) on delete restrict,
 receipt_event_id text not null references private.tc_manual_stripe_bridge_receipts(provider_event_id) on delete restrict,
 provider_account_id text not null,
 mode text not null check(mode in ('test','live')),
 warning_id text not null check(warning_id ~ '^issfr_[A-Za-z0-9]{1,200}$'),
 payment_intent_id text not null check(payment_intent_id ~ '^pi_[A-Za-z0-9]{1,200}$'),
 charge_id text not null check(charge_id ~ '^ch_[A-Za-z0-9]{1,200}$'),
 row_version bigint not null check(row_version between 2 and 9007199254740991),
 kind text not null check(kind in ('provider','review')),
 actor_id uuid references auth.users(id) on delete restrict,
 operation_id uuid unique,
 expected_version bigint,
 provider_event_id text unique check(provider_event_id ~ '^evt_[A-Za-z0-9]{1,200}$'),
 event_proof_sha256 text check(event_proof_sha256 ~ '^[a-f0-9]{64}$'),
 data jsonb not null check(jsonb_typeof(data)='object' and octet_length(data::text)<=3500),
 created_at timestamptz not null default now(),
 unique(case_id,row_version),
 foreign key(provider_account_id,mode) references private.tc_manual_stripe_channels(provider_account_id,mode),
 check((kind='provider' and actor_id is null and operation_id is null and expected_version is null
   and provider_event_id is not null and event_proof_sha256 is not null)
  or (kind='review' and actor_id is not null and operation_id is not null and expected_version=row_version-1
   and expected_version is not null and provider_event_id is null and event_proof_sha256 is null)),
 check(row_version<>2 or (id=case_id and kind='provider'))
);
create unique index tc_subscription_risk_warning_once
 on private.tc_subscription_risk_entries(provider_account_id,mode,warning_id) where row_version=2;
create index tc_subscription_risk_history on private.tc_subscription_risk_entries(case_id,row_version desc);
alter table private.tc_subscription_risk_entries enable row level security;
revoke all on private.tc_subscription_risk_entries from public,anon,authenticated;
create policy tc_subscription_risk_private on private.tc_subscription_risk_entries
 as restrictive for all to public using(false) with check(false);
create trigger tc_subscription_risk_immutable before update or delete or truncate
 on private.tc_subscription_risk_entries for each statement
 execute function private.tc_manual_subscription_intake_reject_mutation();

create function private.tc_subscription_risk_record(p_account text,p_mode text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path='' as $record$
#variable_conflict use_variable
declare t private.tc_manual_subscription_invoice_tasks;r private.tc_payment_requests;
 first_entry private.tc_subscription_risk_entries;previous private.tc_subscription_risk_entries;
 task_uuid uuid;receipt_id text;matches integer;key text;stamp bigint;amount integer;
 intent_id text;charge_id text;invoice_id text;proof jsonb;digest text;version bigint;case_uuid uuid;
begin
 if current_setting('role',true) is distinct from 'service_role' then
  raise exception 'subscription_risk_server_only' using errcode='42501';end if;
 if p_account is null or p_account !~ '^acct_[A-Za-z0-9]{1,100}$' or p_mode is null or p_mode not in ('test','live')
  or jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>3500
  or p_data-array['event_id','event_type','event_created','livemode','warning_id','warning_created',
   'actionable_at_event','actionable_now','fraud_type_at_event','fraud_type_now','payment_intent_id','charge_id',
   'customer_id','charge_amount_cents','currency','invoice_id','subscription_id','invoice_payment_id',
   'invoice_period_start','invoice_period_end']<>'{}'
  or not(p_data ?& array['event_id','event_type','event_created','livemode','warning_id','warning_created',
   'actionable_at_event','actionable_now','fraud_type_at_event','fraud_type_now','payment_intent_id','charge_id',
   'customer_id','charge_amount_cents','currency','invoice_id','subscription_id','invoice_payment_id',
   'invoice_period_start','invoice_period_end'])
  or jsonb_typeof(p_data->'livemode') is distinct from 'boolean'
  or (p_data->>'livemode')::boolean is distinct from (p_mode='live')
  or p_data->>'currency' is distinct from 'EUR'
  or p_data->>'event_id' is null or p_data->>'event_id' !~ '^evt_[A-Za-z0-9]{1,200}$'
  or p_data->>'warning_id' is null or p_data->>'warning_id' !~ '^issfr_[A-Za-z0-9]{1,200}$'
  or p_data->>'payment_intent_id' is null or p_data->>'payment_intent_id' !~ '^pi_[A-Za-z0-9]{1,200}$'
  or p_data->>'charge_id' is null or p_data->>'charge_id' !~ '^ch_[A-Za-z0-9]{1,200}$'
  or (p_data->>'customer_id' is not null and p_data->>'customer_id' !~ '^cus_[A-Za-z0-9]{1,200}$')
  or p_data->>'event_type' is null or p_data->>'event_type' not in
   ('radar.early_fraud_warning.created','radar.early_fraud_warning.updated')
  or not private.tc_subscription_incident_integer(p_data->'event_created',1,9007199254740991)
  or not private.tc_subscription_incident_integer(p_data->'warning_created',1,9007199254740991)
  or not private.tc_subscription_incident_integer(p_data->'charge_amount_cents',1,100000000)
 then raise exception 'subscription_risk_invalid' using errcode='22023';end if;
 foreach key in array array['actionable_at_event','actionable_now'] loop
  if jsonb_typeof(p_data->key) is distinct from 'boolean' then
   raise exception 'subscription_risk_invalid' using errcode='22023';end if;
 end loop;
 foreach key in array array['fraud_type_at_event','fraud_type_now'] loop
  if p_data->>key is null or p_data->>key not in ('card_never_received','fraudulent_card_application',
   'made_with_counterfeit_card','made_with_lost_card','made_with_stolen_card','misc','unauthorized_use_of_card') then
   raise exception 'subscription_risk_invalid' using errcode='22023';end if;
 end loop;
 stamp:=(p_data->>'event_created')::bigint;amount:=(p_data->>'charge_amount_cents')::integer;
 if stamp>extract(epoch from now())+300 or (p_data->>'warning_created')::bigint>stamp then
  raise exception 'subscription_risk_invalid' using errcode='23514';end if;
 intent_id:=p_data->>'payment_intent_id';charge_id:=p_data->>'charge_id';invoice_id:=p_data->>'invoice_id';

 -- Native immutable paid receipt is the ownership boundary. Neither metadata,
 -- a chosen company/task ID, nor a current plan is an authority for binding.
 select count(distinct x.id),min(x.id::text)::uuid,min(b.provider_event_id)
 into matches,task_uuid,receipt_id
 from private.tc_manual_subscription_invoice_tasks x
 join private.tc_manual_stripe_bridge_receipts b on b.task_id=x.id and b.request_id=x.request_id
  and b.provider_account_id=x.provider_account_id and b.provider_payment_id=x.provider_payment_id
 where x.provider_account_id=p_account and b.mode=p_mode
  and ((invoice_id is null and x.provider_invoice_id is null and x.provider_payment_id=intent_id and b.payment_kind='initial_payment')
   or (invoice_id is not null and x.provider_invoice_id=invoice_id and x.provider_payment_id=invoice_id and b.payment_kind='subscription_invoice'));
 if matches<>1 or task_uuid is null or receipt_id is null then
  raise exception 'subscription_risk_mapping_unavailable' using errcode='23514';end if;
 -- Serializes provider observations of one genuine paid task; no task mutation.
 select * into t from private.tc_manual_subscription_invoice_tasks x where x.id=task_uuid for update;
 select * into r from private.tc_payment_requests x where x.id=t.request_id;
 if r.id is null or r.user_id<>t.buyer_user_id or r.quoted_cents<>amount or t.amount_cents<>amount
  or r.currency<>'EUR' or t.currency<>'EUR'
  or not exists(select 1 from public.organizations o where o.id=t.buyer_company_id and o.owner_id=t.buyer_user_id) then
  raise exception 'subscription_risk_payment_mismatch' using errcode='23514';end if;
 if invoice_id is null then
  if jsonb_typeof(p_data->'subscription_id') is distinct from 'null'
   or jsonb_typeof(p_data->'invoice_payment_id') is distinct from 'null'
   or jsonb_typeof(p_data->'invoice_period_start') is distinct from 'null'
   or jsonb_typeof(p_data->'invoice_period_end') is distinct from 'null' then
   raise exception 'subscription_risk_payment_mismatch' using errcode='23514';end if;
 else
  if invoice_id !~ '^in_[A-Za-z0-9]{1,200}$' or p_data->>'subscription_id' is distinct from t.subscription_id
   or p_data->>'invoice_payment_id' is null or p_data->>'invoice_payment_id' !~ '^inpay_[A-Za-z0-9]{1,200}$'
   or not private.tc_subscription_incident_integer(p_data->'invoice_period_start',1,9007199254740991)
   or not private.tc_subscription_incident_integer(p_data->'invoice_period_end',1,9007199254740991)
   or (p_data->>'invoice_period_start')::bigint is distinct from extract(epoch from t.period_start)::bigint
   or (p_data->>'invoice_period_end')::bigint is distinct from extract(epoch from t.period_end)::bigint
   or not exists(select 1 from private.tc_subscription_invoices i
    join private.tc_billing_subscriptions b on b.provider_id=i.subscription_id
    where i.invoice_id=invoice_id and i.subscription_id=t.subscription_id and i.user_id=t.buyer_user_id
     and i.amount_cents=amount and i.period_start=t.period_start and i.period_end=t.period_end
     and b.request_id=t.request_id and b.user_id=t.buyer_user_id and b.customer_id=p_data->>'customer_id') then
   raise exception 'subscription_risk_payment_mismatch' using errcode='23514';end if;
 end if;
 -- Omit mutable GET fields from replay identity. Never rewrite an observation.
 proof:=jsonb_build_object('account',p_account,'mode',p_mode,'event',p_data-array['actionable_now','fraud_type_now']);
 digest:=encode(sha256(convert_to(proof::text,'UTF8')),'hex');
 select * into first_entry from private.tc_subscription_risk_entries e
  where e.provider_account_id=p_account and e.mode=p_mode and e.warning_id=p_data->>'warning_id' and e.row_version=2 for update;
 select * into previous from private.tc_subscription_risk_entries e where e.provider_event_id=p_data->>'event_id';
 if first_entry.id is null then
  case_uuid:=gen_random_uuid();version:=2;
 else
  if first_entry.task_id<>t.id or first_entry.payment_intent_id<>intent_id or first_entry.charge_id<>charge_id then
   raise exception 'subscription_risk_payment_mismatch' using errcode='23514';end if;
  -- A later paid-event receipt for the same task must not change the anchor.
  receipt_id:=first_entry.receipt_event_id;
  case_uuid:=first_entry.id;
  select max(e.row_version)+1 into version from private.tc_subscription_risk_entries e where e.case_id=case_uuid;
 end if;
 if previous.id is not null then
  if previous.case_id<>case_uuid or previous.event_proof_sha256<>digest then
   raise exception 'subscription_risk_conflicting_replay' using errcode='23514';end if;
  return jsonb_build_object('contract','subscription-risk-record-v1','received',true,'duplicate',true,'case_id',case_uuid);
 end if;
 insert into private.tc_subscription_risk_entries(id,case_id,task_id,receipt_event_id,provider_account_id,mode,
  warning_id,payment_intent_id,charge_id,row_version,kind,provider_event_id,event_proof_sha256,data)
 values(case when version=2 then case_uuid else gen_random_uuid() end,case_uuid,t.id,receipt_id,p_account,p_mode,
  p_data->>'warning_id',intent_id,charge_id,version,'provider',p_data->>'event_id',digest,p_data);
 return jsonb_build_object('contract','subscription-risk-record-v1','received',true,'duplicate',false,'case_id',case_uuid);
end;$record$;
revoke all on function private.tc_subscription_risk_record(text,text,jsonb) from public,anon,authenticated;
create function public.tc_subscription_risk_record(p_account text,p_mode text,p_data jsonb)
returns jsonb language sql security invoker set search_path='' as $wrapper$
 select private.tc_subscription_risk_record(p_account,p_mode,p_data);
$wrapper$;
revoke all on function public.tc_subscription_risk_record(text,text,jsonb) from public,anon,authenticated;

create function private.tc_subscription_risk_entry_dto(p_entry private.tc_subscription_risk_entries)
returns jsonb language sql stable set search_path='' as $entry$
 select jsonb_build_object('id',p_entry.id,'row_version',p_entry.row_version,'kind',p_entry.kind,
  'actor_id',p_entry.actor_id,'created_at',p_entry.created_at,
  'provider',case when p_entry.kind='provider' then p_entry.data||jsonb_build_object(
   'event_created',to_timestamp((p_entry.data->>'event_created')::bigint),
   'warning_created',to_timestamp((p_entry.data->>'warning_created')::bigint)) else null end,
  'note',case when p_entry.kind='review' then p_entry.data->>'note' else null end);
$entry$;
revoke all on function private.tc_subscription_risk_entry_dto(private.tc_subscription_risk_entries) from public,anon,authenticated;

create function private.tc_subscription_risk_case_dto(p_case uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $dto$
declare first_entry private.tc_subscription_risk_entries;observed private.tc_subscription_risk_entries;
 reviewed private.tc_subscription_risk_entries;t private.tc_manual_subscription_invoice_tasks;version bigint;
begin
 select * into first_entry from private.tc_subscription_risk_entries where id=p_case and row_version=2;
 if first_entry.id is null then raise exception 'subscription_risk_not_found' using errcode='42501';end if;
 select * into t from private.tc_manual_subscription_invoice_tasks where id=first_entry.task_id;
 select * into observed from private.tc_subscription_risk_entries where case_id=p_case and kind='provider' order by row_version desc limit 1;
 select * into reviewed from private.tc_subscription_risk_entries where case_id=p_case and kind='review' order by row_version desc limit 1;
 select max(row_version) into version from private.tc_subscription_risk_entries where case_id=p_case;
 return jsonb_build_object('id',p_case,'task_id',t.id,'buyer_company_id',t.buyer_company_id,
  'buyer_company_name',t.buyer_company_name,'provider_payment_id',t.provider_payment_id,
  'invoice_id',t.provider_invoice_id,'period_start',t.period_start,'period_end',t.period_end,
  'amount_cents',t.amount_cents,'currency','EUR','mode',first_entry.mode,
  'warning_id',first_entry.warning_id,'row_version',version,'created_at',first_entry.created_at,
  'review_state',case when coalesce(reviewed.row_version,0)>observed.row_version then 'reviewed' else 'pending' end,
  'latest_provider',private.tc_subscription_risk_entry_dto(observed),
  'last_review',case when reviewed.id is null then null else private.tc_subscription_risk_entry_dto(reviewed) end);
end;$dto$;
revoke all on function private.tc_subscription_risk_case_dto(uuid) from public,anon,authenticated;

create function private.tc_admin_subscription_risk(
 p_action text,p_case_id uuid default null,p_expected bigint default null,p_operation_id uuid default null,
 p_data jsonb default '{}',p_after uuid default null
) returns jsonb language plpgsql security definer set search_path='' as $admin$
declare actor uuid;first_entry private.tc_subscription_risk_entries;previous private.tc_subscription_risk_entries;
 inserted private.tc_subscription_risk_entries;rows jsonb;tail uuid;version bigint;before_version bigint;next_before bigint;
begin
 actor:=private.tc_manual_subscription_operator();
 if jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>3500 then
  raise exception 'subscription_risk_invalid' using errcode='22023';end if;
 if p_action='capabilities' then
  return jsonb_build_object('contract','subscription-risk-v1','available',true,'informational_only',true,
   'refunds_available',false,'license_changes_available',false,'fiscal_emission_available',false);
 end if;
 if p_action in ('list','detail') then
  if p_data<>'{}' or (p_action='detail' and p_case_id is null) then
   raise exception 'subscription_risk_invalid' using errcode='22023';end if;
  select coalesce(jsonb_agg(private.tc_subscription_risk_case_dto(q.id) order by q.id),'[]') into rows
  from (select id from private.tc_subscription_risk_entries
   where row_version=2 and (p_action<>'detail' or id=p_case_id) and (p_after is null or id>p_after) order by id limit 50) q;
  tail:=case when jsonb_array_length(rows)=50 then (rows->49->>'id')::uuid else null end;
  return jsonb_build_object('contract','subscription-risk-v1','items',rows,'next_cursor',tail);
 end if;
 if p_action='history' then
  if p_case_id is null or p_data-array['before_version']<>'{}'
   or (p_data ? 'before_version' and not private.tc_subscription_incident_integer(p_data->'before_version',2,9007199254740991))
   or not exists(select 1 from private.tc_subscription_risk_entries where id=p_case_id and row_version=2) then
   raise exception 'subscription_risk_invalid' using errcode='22023';end if;
  before_version:=(p_data->>'before_version')::bigint;
  select coalesce(jsonb_agg(private.tc_subscription_risk_entry_dto(q::private.tc_subscription_risk_entries) order by q.row_version desc),'[]') into rows
  from (select * from private.tc_subscription_risk_entries where case_id=p_case_id
   and (before_version is null or row_version<before_version) order by row_version desc limit 50) q;
  next_before:=case when jsonb_array_length(rows)=50 then (rows->49->>'row_version')::bigint else null end;
  return jsonb_build_object('contract','subscription-risk-v1','case_id',p_case_id,'items',rows,'next_before_version',next_before);
 end if;
 if p_action is distinct from 'review' or p_case_id is null or p_operation_id is null or p_expected is null
  or p_expected<2 or p_expected>=9007199254740991 or p_data-array['note']<>'{}'
  or jsonb_typeof(p_data->'note') is distinct from 'string' or char_length(btrim(p_data->>'note')) not between 3 and 1000
  or p_data->>'note'<>btrim(p_data->>'note') or p_data->>'note' ~ '[[:cntrl:]]' then
  raise exception 'subscription_risk_invalid' using errcode='22023';end if;
 select * into first_entry from private.tc_subscription_risk_entries where id=p_case_id and row_version=2 for update;
 if first_entry.id is null then raise exception 'subscription_risk_not_found' using errcode='42501';end if;
 actor:=private.tc_manual_subscription_operator();
 select * into previous from private.tc_subscription_risk_entries where operation_id=p_operation_id;
 if previous.id is not null then
  if previous.case_id<>p_case_id or previous.actor_id<>actor or previous.expected_version<>p_expected
   or previous.data<>p_data or previous.kind<>'review' then
   raise exception 'subscription_risk_conflicting_replay' using errcode='23514';end if;
  inserted:=previous;
 else
  select max(row_version) into version from private.tc_subscription_risk_entries where case_id=p_case_id;
  if version<>p_expected then raise exception 'subscription_risk_version_conflict' using errcode='40001';end if;
  insert into private.tc_subscription_risk_entries(case_id,task_id,receipt_event_id,provider_account_id,mode,
   warning_id,payment_intent_id,charge_id,row_version,kind,actor_id,operation_id,expected_version,data)
  values(p_case_id,first_entry.task_id,first_entry.receipt_event_id,first_entry.provider_account_id,first_entry.mode,
   first_entry.warning_id,first_entry.payment_intent_id,first_entry.charge_id,version+1,'review',actor,p_operation_id,version,p_data)
  returning * into inserted;
 end if;
 return jsonb_build_object('contract','subscription-risk-v1','case',private.tc_subscription_risk_case_dto(p_case_id),
  'replayed',previous.id is not null,'operation',jsonb_build_object('id',inserted.operation_id,'actor_id',inserted.actor_id,
   'expected_version',inserted.expected_version,'applied_version',inserted.row_version,'note',inserted.data->>'note'));
end;$admin$;
revoke all on function private.tc_admin_subscription_risk(text,uuid,bigint,uuid,jsonb,uuid) from public,anon,authenticated;
grant execute on function private.tc_admin_subscription_risk(text,uuid,bigint,uuid,jsonb,uuid) to authenticated;
create function public.tc_admin_subscription_risk(
 p_action text,p_case_id uuid default null,p_expected bigint default null,p_operation_id uuid default null,
 p_data jsonb default '{}',p_after uuid default null
) returns jsonb language sql security invoker set search_path='' as $wrapper$
 select private.tc_admin_subscription_risk(p_action,p_case_id,p_expected,p_operation_id,p_data,p_after);
$wrapper$;
revoke all on function public.tc_admin_subscription_risk(text,uuid,bigint,uuid,jsonb,uuid) from public,anon;
grant execute on function public.tc_admin_subscription_risk(text,uuid,bigint,uuid,jsonb,uuid) to authenticated;

do $service_acl$
begin
 if exists(select 1 from pg_roles where rolname='service_role') then
  revoke all on private.tc_subscription_risk_entries from service_role;
  revoke all on function private.tc_subscription_risk_entry_dto(private.tc_subscription_risk_entries),
   private.tc_subscription_risk_case_dto(uuid),private.tc_admin_subscription_risk(text,uuid,bigint,uuid,jsonb,uuid),
   public.tc_admin_subscription_risk(text,uuid,bigint,uuid,jsonb,uuid) from service_role;
  grant execute on function private.tc_subscription_risk_record(text,text,jsonb),
   public.tc_subscription_risk_record(text,text,jsonb) to service_role;
 end if;
end;$service_acl$;
